// Get current execution details
const now = new Date();
const workflowId = $workflow.id;
const executionId = $execution.id;

// Format timestamp for IST
const istOffset = 5.5 * 60 * 60 * 1000; // IST is UTC+5:30
const istTime = new Date(now.getTime() + istOffset);
const timestamp = istTime.toISOString().replace('T', ' ').substring(0, 19);

// Generate unique run ID
const runId = `run-${istTime.toISOString().split('T')[0]}-${executionId}`;

// Return execution metadata
return {
  json: {
    runId: runId,
    executionId: executionId,
    workflowId: workflowId,
    timestamp: timestamp,
    date: istTime.toISOString().split('T')[0],
    time: istTime.toTimeString().split(' ')[0],
    timezone: 'IST',
    module: 'Module 1 - Scheduler',
    status: 'Started',
    message: 'Workflow execution initiated successfully'
  }
};

// Health check failed - log warning
const metadata = $('Generate Execution Metadata').first().json;

return {
  json: {
    ...metadata,
    status: 'Warning',
    message: 'Health check failed but continuing workflow execution',
    healthStatus: 'Unhealthy'
  }
};

// Health check passed
const metadata = $('Generate Execution Metadata').first().json;

return {
  json: {
    ...metadata,
    status: 'Success',
    message: 'Health check passed - system healthy',
    healthStatus: 'Healthy'
  }
};
